Use the time module and a wrapper function:

import time

def timed(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        print(f"{func.__name__} took {end-start:.6f} seconds")
        return result
    return wrapper

@timed
def my_func():
    time.sleep(1)

