Define __iter__ to return an iterator object (often self) and __next__ to return the next item or raise StopIteration. Example:

class NumberRange:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.current = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.current >= self.end:
            raise StopIteration
        val = self.current
        self.current += 1
        return val

for n in NumberRange(0, 5):
    print(n)  # prints 0 to 4
